<?= $this->extend('layouts/admin') ?><?= $this->section('content') ?><section class="list-head"><div><p>Configuration</p><h1>Site settings</h1></div></section><form class="editor-form" method="post" action="<?= site_url('admin/settings') ?>"><?= csrf_field() ?><?php foreach (['site_name' => 'Site name', 'site_tagline' => 'Tagline', 'contact_email' => 'Contact email', 'contact_phone' => 'Contact phone', 'logo' => 'Logo path / URL', 'address' => 'Address', 'footer_text' => 'Footer description', 'inquiry_recipient_email' => 'Inquiry notification recipient', 'inquiry_sender_email' => 'Inquiry notification sender'] as $key => $label): ?><label class="<?= in_array($key, ['address', 'footer_text']) ? 'wide' : '' ?>"><?= esc($label) ?><?php if (in_array($key, ['address', 'footer_text'])): ?><textarea name="<?= $key ?>" rows="4"><?= esc($settings[$key] ?? '') ?></textarea><?php else: ?><input <?= str_ends_with($key, '_email') ? 'type="email"' : '' ?> name="<?= $key ?>" value="<?= esc($settings[$key] ?? '') ?>"><?php endif ?></label><?php endforeach ?><p class="field-help wide">Inquiry email delivery is attempted only when both notification addresses are configured. SMTP credentials belong in the deployment environment, never in the CMS.</p><div class="form-actions"><button class="primary">Save settings</button></div></form><?= $this->endSection() ?>
